class Solution {
public:
    int smallestNumber(int n, int t) {
        for (int curr = n; ; ++curr) {
            int prod = 1;
            int tmp = curr;
            while (tmp > 0) {
                prod *= (tmp % 10);
                tmp /= 10;
            }
            if (prod % t == 0) return curr;
        }
    }
};

class Solution {
    public int smallestNumber(int n, int t) {
        for (int curr = n; ; curr++) {
            int prod = 1;
            int tmp = curr;
            while (tmp > 0) {
                prod *= (tmp % 10);
                tmp /= 10;
            }
            if (prod % t == 0) return curr;
        }
    }
}

var smallestNumber = function(n, t) {
    for (let curr = n; ; curr++) {
        let prod = 1;
        let tmp = curr;
        while (tmp > 0) {
            prod *= (tmp % 10);
            tmp = Math.floor(tmp / 10);
        }
        if (prod % t === 0) return curr;
    }
};
